 "content": "def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        vals = set(row)
        if len(vals) == 2:
            # A partial stripe keeps its leading run and the remaining cells
            # become color 1, as shown by the demonstration.
            first = row[0]
            n = 0
            for value in row:
                if value == first:
                    n += 1
                else:
                    break
            if 0 < n < len(row):
                row[n:] = [1] * (len(row) - n)
    return out
